using ChaChing.Domain.Common;

namespace ChaChing.Domain.Billing
{
    /// <summary>The public reference of a sent document, e.g. DEV-2026-0042 or FAC-2026-0042. Received when the document is sent, never generated by the domain (ADR 0013).</summary>
    public record BillingNumber(TypeDocument TypeDocument, int Year, int Sequence)
    {
        public TypeDocument TypeDocument { get; } = ArgumentValidator.Enum(TypeDocument, nameof(TypeDocument));

        public int Year { get; } = ValidateYear(Year);

        public int Sequence { get; } = ValidateSequence(Sequence);

        public override string ToString() => $"{TypeDocument}-{Year}-{Sequence:D4}";

        static int ValidateYear(int year)
        {
            if (year < 2000 || year > 9999)
                throw new ArgumentOutOfRangeException(nameof(year), "The year must have 4 digits, from 2000.");
            return year;
        }

        static int ValidateSequence(int sequence)
        {
            if (sequence < 1)
                throw new ArgumentOutOfRangeException(nameof(sequence), "The sequence starts at 1.");
            return sequence;
        }

        public BillingNumber ValidateType(TypeDocument typeExpected)
        {
            if (typeExpected != TypeDocument)
                throw new InvalidOperationException("The number is invalid for this type of document.");
            return this;
        }
    }
}
